<!doctype html><html><head><meta charset="utf-8"><title><?=esc($invoice['invoice_no'])?></title><style>@page{size:A4;margin:11mm 12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#111;font-size:12px;margin:0}.head{display:grid;grid-template-columns:150px 1fr;border-bottom:1.5px solid #222;padding-bottom:8px}.logo{width:145px;max-height:78px;object-fit:contain}.firm{text-align:right;line-height:1.35}.firm b{font-size:17px}.adv{font-weight:700;margin-top:8px}.title{text-align:center;font-size:17px;font-weight:800;text-decoration:underline;margin:5px}.box{border:1px solid #222}.meta{display:grid;grid-template-columns:1fr 120px;border-bottom:1px solid #222}.meta>div{padding:6px}.meta>div+div{border-left:1px solid #222;text-align:center;font-weight:700}.to{min-height:185px;padding:8px;border-right:1px solid #222}.label{font-weight:800;text-decoration:underline;font-size:13px}.narr{line-height:1.45}.items{width:100%;border-collapse:collapse}.items th,.items td{border:1px solid #222;padding:5px 7px;vertical-align:top}.items th{text-align:left}.amount{text-align:right;width:100px}.remit{padding:7px;border:1px solid #222;border-top:0;line-height:1.42}.total{display:grid;grid-template-columns:1fr 100px;border:1px solid #222;border-top:0;font-weight:800}.total>div{padding:6px}.total>div+div{border-left:1px solid #222;text-align:right}.footer{font-weight:800;margin-top:9px}@media print{.no-print{display:none}}</style></head><body><div class="head"><div><img class="logo" src="<?=base_url('assets/lex-factum-original.png')?>"></div><div class="firm"><b>Lex Factum &amp; Partners</b><br>Law Firm &amp; IP Attorney<br>1st Floor, Vikas Kendra,<br>E Block LSC, Vikaspuri,<br>Delhi - 110018, India<br>P.: +91 91529 46757<br>E.: office@lexfactum.com<br>W.: www.lexfactum.com</div></div><div class="adv"><?=esc($invoice['advocate_name'])?><br><span style="font-weight:400">Advocate</span></div><div class="title">ACTUAL/PROFESSIONAL INVOICE</div><div class="box"><div class="meta"><div>Invoice Number: <?=esc($invoice['invoice_no'])?></div><div>Amount<br>in INR</div><div class="to"><span class="label">To,</span><br><b><?=esc($invoice['client_name'])?></b><br><?=nl2br(esc($invoice['client_address']))?><?php if($invoice['client_email']):?><br><?=esc($invoice['client_email'])?><?php endif;?><?php if($invoice['client_phone']):?><br><?=esc($invoice['client_phone'])?><?php endif;?><br><br><span class="label">NARRATION:</span><div class="narr"><b>Our Professional charges</b><br><?=nl2br(esc($invoice['narration']))?><?php if($invoice['case_reference']):?><br><br><b>Case / Matter Reference:</b> <?=esc($invoice['case_reference'])?><?php endif;?></div></div><div><?=date('jS M Y',strtotime($invoice['invoice_date']))?></div></div><table class="items"><tr><th>Description</th><th style="width:145px">Rate (INR)</th><th class="amount">Amount</th></tr><?php foreach($items as $x):?><tr><td><?=nl2br(esc($x['description']))?></td><td><b><?=rtrim(rtrim(number_format($x['rate'],2,'.',''),'0'),'.')?> x <?=rtrim(rtrim(number_format($x['quantity'],2,'.',''),'0'),'.')?></b></td><td class="amount"><?=number_format($x['amount'],2)?></td></tr><?php endforeach;?><?php if($invoice['adjustment']!=0):?><tr><td colspan="2"><b>Adjustment</b></td><td class="amount"><?=number_format($invoice['adjustment'],2)?></td></tr><?php endif;?><?php if($invoice['tax_amount']!=0):?><tr><td colspan="2"><b>Tax</b></td><td class="amount"><?=number_format($invoice['tax_amount'],2)?></td></tr><?php endif;?></table><div class="remit"><b><u>Remittance Instructions: Through Online/Wire Transfer</u></b><br>Name of Account- <b>LEX FACTUM &amp; PARTNERS</b><br>Account No.-------- <b><?=esc($invoice['bank_account'])?></b><br>Name of Bank ----- <b><?=esc($invoice['bank_name'])?></b><br>Branch Address--- <?=esc($invoice['bank_branch'])?><br>IFSC --------------- <?=esc($invoice['bank_ifsc'])?><br>PAN for TDS if Applicable- <b><?=esc($invoice['pan'])?></b></div><div class="total"><div>Total: <?=esc($invoice['amount_words'])?></div><div><?=number_format($invoice['total'],2)?></div></div></div><div class="footer">DIGITALLY GENERATED AND ELECTRONICALLY COMMUNICATED INVOICE.<br>NO SIGNATURES NEEDED</div><script>if(location.search.includes('autoprint=1'))window.addEventListener('load',()=>setTimeout(()=>window.print(),250));</script></body></html>
